// THE interface of the mocked sub-agents (TestCases/test_folders/agent_fixture). Nothing else may describe a result, its input, the index or a guard rule.
//   results/<suite>/<file>.ts  default export `ResultModule`, `satisfies ResultModule`; <suite> = the TestCases/test_folders/<suite> folder whose cases expect it
//   index.json           `IndexRow[]` (with `suite`), GENERATED by `bun test_harness/core/build_index.ts`; fixture_policy.ts fails when it is stale
//   store/*_rules.json   `Record<role, Rule>`, picked by `Case.guard`
/** Inline fixture (unit tests only). Real recorded work lives in TestCases/test_folders/agent_fixture/results/<id>.ts as `ResultModule`. */
export type Fixture = {
  id: string;
  agent?: string;
  keywords?: string[];
  question?: string;
  response: string;
  files?: Record<string, string>;
};

/** What a recorded `run` receives. Everything it needs to do the "sub-agent's work" without a model. */
export type Req = {
  /** The agent type that was called (e.g. "writer"). */
  agent: string;
  /** The full task text the lead handed over (the prompt). */
  task: string;
  /** Workspace (run_test/): where the produced files must land. */
  ws: string;
  /** TestCases/test_folders/agent_fixture/store/: the source files the script copies from. */
  store: string;
  /** Copy store/<from> (file or folder) into ws/<to> (default: ws root). Returns the relative file paths written. */
  cp(from: string, to?: string): string[];
  /** Write a small file into the workspace. */
  write(path: string, text: string): void;
};

/**
 * TestCases/test_folders/agent_fixture/results/<id>.ts default export. A recorded sub-agent result: ONLY `run(req)`.
 * `run` does the work (cp from TestCases/test_folders/agent_fixture/store/..., write files) and returns the reply text. No static response, no setup.
 * Never delete one: it is what saves sub-agent tokens. TestCases/test_folders/agent_fixture/index.json is generated from these (bun core/build_index.ts).
 */
export type ResultModule = {
  id: string;
  title: string;
  description: string;
  /** How the harness finds it. `keywords` (ALL in the task, lowercase) wins; otherwise similarity of the task to `expected_input.text`. */
  match?: { agent?: string; keywords?: string[]; /** only eligible once THIS result id was already served in the same task (rework: the `_fix` answer follows the incomplete one, whatever words the lead uses) */ after?: string;
  /** true = this result may be served MANY times (a generator command called with a different name / options each time). Without it, a result is served once per task and a repeat is answered "already done" from the session table. A check question is still answered from the table. */
  repeatable?: boolean };
  expected_input: {
    /** The question this answer was recorded for. */
    text: string;
    /** What a correct hand-over must contain (documentation for the guard). */
    guardrails_test: string;
  };
  run(req: Req): string;
};

/** One row of TestCases/test_folders/agent_fixture/index.json: find a result without opening it. */
export type IndexRow = { id: string; /** folder name of the owning suite = results/<suite>/ */ suite: string; file: string; title: string; agent?: string; keywords?: string[]; text: string; copies?: string[] };


/** One role's hand-over rule (store/<name>_rules.json: { <role>: Rule }). */
export type Rule = {
  /** Roles that must already be done before this one may be called (role order). */
  requires_done?: string[];
  /** Words the hand-over must ALL contain (case-insensitive), e.g. "run_test", "PLAN.md". */
  contains_all?: string[];
  /** Minimum hand-over length. */
  min_chars?: number;
  /** true = distractor: calling it fails the case. */
  forbidden?: boolean;
};
